// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title NetworkProxy
 * @notice A proxy contract that routes calls to registered backend implementations
 *         with graceful shutdown handling for migration scenarios.
 */
contract NetworkProxy is Ownable {
    enum ProxyState { ACTIVE, DRAINING, SHUTDOWN }

    ProxyState public state;

    // Registry of approved backend implementations
    mapping(bytes4 => address) private _implementations;

    // Pending migration target for graceful shutdown
    address private _migrationTarget;

    // Timestamp when draining started
    uint256 private _drainStartTime;

    // Grace period for draining (default 1 hour)
    uint256 public constant DRAIN_PERIOD = 3600;

    // Nonce for replay protection
    mapping(address => uint256) public nonces;

    // Whitelist of approved redirect targets
    mapping(address => bool) private _approvedTargets;

    event ImplementationRegistered(bytes4 indexed selector, address implementation);
    event DrainInitiated(address migrationTarget, uint256 timestamp);
    event ShutdownComplete(address migrationTarget);
    event TargetApproved(address target);
    event TargetRevoked(address target);

    modifier whenActive() {
        require(state == ProxyState.ACTIVE, "Proxy: not active");
        _;
    }

    modifier whenNotShutdown() {
        require(state != ProxyState.SHUTDOWN, "Proxy: shutdown");
        _;
    }

    constructor() Ownable() {
        state = ProxyState.ACTIVE;
    }

    /**
     * @notice Register an implementation for a specific function selector
     * @param selector The 4-byte function selector
     * @param impl The implementation contract address
     */
    function registerImplementation(bytes4 selector, address impl) external onlyOwner whenActive {
        require(impl != address(0), "Proxy: zero address");
        require(_isContract(impl), "Proxy: not a contract");
        _implementations[selector] = impl;
        emit ImplementationRegistered(selector, impl);
    }

    /**
     * @notice Approve a target address for redirects
     */
    function approveTarget(address target) external onlyOwner {
        require(target != address(0), "Proxy: zero address");
        require(_isContract(target), "Proxy: not a contract");
        _approvedTargets[target] = true;
        emit TargetApproved(target);
    }

    /**
     * @notice Revoke a target address
     */
    function revokeTarget(address target) external onlyOwner {
        _approvedTargets[target] = false;
        emit TargetRevoked(target);
    }

    /**
     * @notice Initiate graceful shutdown with migration to new proxy
     * @param migrationTarget The new proxy to redirect to after drain
     */
    function initiateGracefulShutdown(address migrationTarget) external onlyOwner whenActive {
        require(migrationTarget != address(0), "Proxy: zero migration target");
        require(_isContract(migrationTarget), "Proxy: target not contract");
        require(_approvedTargets[migrationTarget], "Proxy: target not approved");

        _migrationTarget = migrationTarget;
        _drainStartTime = block.timestamp;
        state = ProxyState.DRAINING;

        emit DrainInitiated(migrationTarget, block.timestamp);
    }

    /**
     * @notice Complete shutdown after drain period
     */
    function completeShutdown() external onlyOwner {
        require(state == ProxyState.DRAINING, "Proxy: not draining");
        require(block.timestamp >= _drainStartTime + DRAIN_PERIOD, "Proxy: drain period active");

        state = ProxyState.SHUTDOWN;
        emit ShutdownComplete(_migrationTarget);
    }

    /**
     * @notice Get the current migration target (for clients to discover new endpoint)
     */
    function getMigrationTarget() external view returns (address) {
        return _migrationTarget;
    }

    /**
     * @notice Emergency redirect - allows owner to set migration target during drain
     *         without re-initiating the full shutdown sequence. Used when the original
     *         migration target has issues and a new one must be substituted.
     * @param newTarget The replacement migration target
     * @param ownerSig Owner signature authorizing the change (for multisig compat)
     */
    function emergencyRedirect(address newTarget, bytes calldata ownerSig) external whenNotShutdown {
        // Verify the caller has a valid nonce-based authorization
        bytes32 messageHash = keccak256(abi.encodePacked(
            address(this),
            newTarget,
            nonces[owner()],
            block.chainid
        ));
        bytes32 ethSignedHash = _toEthSignedMessageHash(messageHash);

        address signer = _recoverSigner(ethSignedHash, ownerSig);
        require(signer == owner(), "Proxy: invalid signature");

        // Increment nonce for replay protection
        nonces[owner()]++;

        // During DRAINING state, allow target substitution
        // During ACTIVE state, this pre-sets the migration target
        _migrationTarget = newTarget;
    }

    /**
     * @notice Fallback that delegates calls or redirects based on state
     */
    fallback() external payable whenNotShutdown {
        if (state == ProxyState.DRAINING && block.timestamp >= _drainStartTime + DRAIN_PERIOD) {
            // Drain period elapsed, redirect to migration target
            _redirectCall(_migrationTarget);
        } else {
            // Normal delegation
            address impl = _implementations[msg.sig];
            require(impl != address(0), "Proxy: no implementation");
            _delegateCall(impl);
        }
    }

    receive() external payable {}

    // --- Internal functions ---

    function _redirectCall(address target) internal {
        // Perform a call to the target with the same calldata
        (bool success, bytes memory returnData) = target.call{value: msg.value}(msg.data);
        if (success) {
            assembly {
                return(add(returnData, 0x20), mload(returnData))
            }
        } else {
            assembly {
                revert(add(returnData, 0x20), mload(returnData))
            }
        }
    }

    function _delegateCall(address impl) internal {
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    function _isContract(address account) internal view returns (bool) {
        uint256 size;
        assembly { size := extcodesize(account) }
        return size > 0;
    }

    function _toEthSignedMessageHash(bytes32 hash) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash));
    }

    function _recoverSigner(bytes32 hash, bytes memory sig) internal pure returns (address) {
        require(sig.length == 65, "Proxy: invalid sig length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(sig, 32))
            s := mload(add(sig, 64))
            v := byte(0, mload(add(sig, 96)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "Proxy: invalid sig v");
        return ecrecover(hash, v, r, s);
    }
}
